// Shared FIXTURE builders for the direction / next-move / breakout-tf tests.
// REBUILT: the original file was missing from the delivered ZIP (six test files import it).
// It is a reconstruction from how the engines read their input (src/screens/DirectionEngine.js)
// and how the tests call it. Every number is generated by a fixed formula - this is MOCK data for
// unit tests, never provider data.
//   makePayload(opts) -> the object computeDirection(data, ...) expects
//   makeBars(kind, n, base) -> daily candles { t, o, h, l, c, v }
//   (default Bank Nifty bar kind follows Nifty, except a falling Bank Nifty day move beside a rising Nifty - the conflict case)
//   NOW -> the fixed "current time" used by the tests (Tue 13 Oct 2026, 10:30 IST, market open)
export var NOW = Date.UTC(2026, 9, 13, 5, 0, 0);
var DAY = 86400000;

// kind: up | down | range | rangeBreakUp | rangeBreakDown. Last bar ends at lastT (default NOW).
export function makeBars(kind, n, base, lastT){
  n = n || 60; base = base || 24000;
  var end = lastT != null ? lastT : NOW;
  var out = [], i;
  for(i = 0; i < n; i++){
    var close, step = base * 0.004;
    // trends keep a small pullback on the last bars so they stay inside the recent range (no fresh breakout)
    var pull = i >= n - 3 ? step * 1.2 : 0;
    if(kind == "up") close = base + (i - n) * step * 0.6 + Math.sin(i) * step * 0.2 - pull;
    else if(kind == "down") close = base - (i - n) * step * 0.6 + Math.sin(i) * step * 0.2 + pull;
    else close = base + Math.sin(i * 0.9) * step * 1.5;                      // range / break kinds
    if(kind == "rangeBreakUp" && i >= n - 2) close = base + step * (i == n - 1 ? 5 : 4);   // two completed closes above every earlier high
    if(kind == "rangeBreakDown" && i >= n - 2) close = base - step * (i == n - 1 ? 5 : 4);
    var open = i == 0 ? close : out[i - 1].c;
    var hi = Math.max(open, close) + step * 0.3, lo = Math.min(open, close) - step * 0.3;
    out.push({ t: end - (n - 1 - i) * DAY, o: open, h: hi, l: lo, c: close, v: 1000000 + i * 1000 });
  }
  return out;
}

// opts: niftyKind, bnKind, niftyChg, bnChg, vixChg, crudeChg, sectorsUp, session, status, ts,
//       noNifty, noHistory, noVix, noSectors
export function makePayload(o){
  o = o || {};
  var status = o.status || "LIVE";
  var session = o.session || "OPEN";
  var ts = o.ts != null ? o.ts : NOW - 20000;
  var niftyKind = o.niftyKind || "up", bnKind = o.bnKind || (o.bnChg != null && o.bnChg < 0 && niftyKind == "up" ? "down" : niftyKind);
  var niftyChg = o.niftyChg != null ? o.niftyChg : 0.6;
  var bnChg = o.bnChg != null ? o.bnChg : 0.7;
  function q(ltp, chg){ return { ltp:ltp, chgPct:chg, freshness:{ status:status, sourceTimestamp:ts } }; }
  var indices = {};
  if(!o.noNifty) indices.NIFTY = q(24500, niftyChg);
  indices.BANKNIFTY = q(52000, bnChg);
  if(!o.noVix) indices.VIX = q(14.2, o.vixChg != null ? o.vixChg : 0.5);
  var dh = {};
  if(!o.noHistory){
    dh.NIFTY = { status:"DELAYED", candles:makeBars(niftyKind, 60, 24000, NOW) };
    dh.BANKNIFTY = { status:"DELAYED", candles:makeBars(bnKind, 60, 52000, NOW) };
  }
  var up = o.sectorsUp != null ? o.sectorsUp : 8, items = [];
  for(var i = 0; i < 12; i++) items.push({ name:"SECTOR" + i, chgPct: i < up ? 0.5 : -0.5, ts:ts });
  var sectors = o.noSectors ? { status:"UNAVAILABLE", items:[] } : { status:status, items:items };
  var gItems = [{ name:"S&P 500", chgPct:0.3, freshness:"LIVE", ts:ts }];
  if(o.crudeChg != null) gItems.push({ name:"Crude Oil (WTI)", chgPct:o.crudeChg, freshness:"LIVE", ts:ts });
  return { indices:indices, directionHistory:dh, sectors:sectors, global:{ items:gItems }, macro:{ crude:{ lastBarTs:ts, vol10Pct:1.5, status:"LIVE" }, natGas:{ chgPct:1.0, freshness:"LIVE", ts:ts } }, unavailable:{}, session:session, generatedAt:NOW - 5000 };
}
